css:
.toggle {
  position: relative;
  box-sizing: border-box;
}
.toggle input[type="checkbox"] {
  position: absolute;
  left: 0;
  top: 0;
  z-index: 10;
  width: 100%;
  height: 100%;
  cursor: pointer;
  opacity: 0;
}
.toggle label {
  position: relative;
  display: flex;
  box-sizing: border-box;
}
.toggle label:before {
  content: "";
  width: 28px;
  height: 60px;
  background: linear-gradient(#bbb, #bbb) no-repeat center;
  background-size: 2px 64px;
  display: inline-block;
  transition: 0.2s ease-in;
}
.toggle label:after {
  content: "";
  position: absolute;
  width: 28px;
  height: 28px;
  border: 6px solid #bbb;
  border-radius: 50%;
  left: 0;
  top: 0;
  z-index: 2;
  background: #fff;
  box-sizing: border-box;
  transition: 0.2s ease-in;
}
.toggle input[type="checkbox"]:checked + label:before {
  background-image: linear-gradient(#77c2bb, #77c2bb);
}
.toggle input[type="checkbox"]:checked + label:after {
  top: 32px;
  border-color: #009688;
}
